  requireThat(batch.schemaVersion === 1 && batch.baselineVersion === "codex-cli 0.147.0", "batch is not a verified baseline installation");
  requireThat(path.resolve(batch.reviewerRoot) === REVIEWER, "reviewer root mismatch");
